<style>
.wa131-pair{border:1px solid #d9e7ed;border-radius:12px;background:#fafdfd;margin:16px 0 18px;padding:18px;color:#15374a}
.wa131-pair-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}
.wa131-pair-head strong{display:block;font-size:14px}.wa131-pair-head small{display:block;font-size:11px;color:#718698;margin-top:4px}
.wa131-pair-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.wa131-pair-card{padding:15px;border:1px solid #dbe6eb;border-radius:10px;background:white;min-width:0}
.wa131-pair-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:9px;font-size:13px}
.wa131-pill{font-size:10px;padding:5px 9px;border-radius:999px;background:#edf3f6;color:#667f8f}.wa131-pill.connected{background:#e6f7ef;color:#117f69}
.wa131-pair-actions{display:flex;gap:8px;flex-wrap:wrap}.wa131-btn{background:#fff;border:1px solid #bcd9d7;padding:10px 13px;border-radius:7px;color:#087e75;font-weight:700;font-size:12px;cursor:pointer}
.wa131-btn.primary{background:#008c83;color:#fff;border-color:#008c83}.wa131-btn:disabled{opacity:.5;cursor:not-allowed}
.wa131-caption{font-size:11px;color:#6e8493;line-height:1.6;margin-top:10px;display:block}
.wa131-qr{background:#f4f9f7;border-radius:10px;margin-top:12px;padding:15px;text-align:center}.wa131-qr img{width:256px;height:256px;max-width:100%;background:white;padding:9px;border-radius:8px;display:block;margin:auto}
.wa131-qr p{font-size:12px;line-height:1.5;margin:10px auto 0;max-width:350px;color:#456577}
.wa131-notice{background:#eaf8f3;color:#08725f;padding:9px 12px;border-radius:7px;font-size:12px;margin-top:10px}.wa131-error{background:#fff3ef;color:#a24836;padding:9px 12px;border-radius:7px;font-size:11px;margin-top:10px}
@media(max-width:800px){.wa131-pair-grid{grid-template-columns:1fr}}
</style>
